from fastapi import FastAPI, Depends, HTTPException
from fastapi.security import APIKeyQuery
from fastapi.testclient import TestClient
import pytest

app = FastAPI()
query_scheme = APIKeyQuery(name="api_key")

@app.get("/")
async def read_items(api_key: str = Depends(query_scheme)):
    return {"api_key": api_key}

client = TestClient(app)

def test_apikey_query_default_401():
    response = client.get("/")
    assert response.status_code == 401
    assert response.headers["www-authenticate"] == 'ApiKey in="query", name="api_key"'

app2 = FastAPI()
query_scheme_403 = APIKeyQuery(name="api_key", not_authenticated_status_code=403)

@app2.get("/")
async def read_items_403(api_key: str = Depends(query_scheme_403)):
    return {"api_key": api_key}

client2 = TestClient(app2)

def test_apikey_query_custom_403():
    response = client2.get("/")
    assert response.status_code == 403
    assert "www-authenticate" not in response.headers

if __name__ == "__main__":
    try:
        test_apikey_query_default_401()
        print("test_apikey_query_default_401 passed")
    except Exception as e:
        print(f"test_apikey_query_default_401 failed: {e}")

    try:
        test_apikey_query_custom_403()
        print("test_apikey_query_custom_403 passed")
    except Exception as e:
        print(f"test_apikey_query_custom_403 failed: {e}")

from fastapi import FastAPI, Depends, HTTPException
from fastapi.security import APIKeyQuery, APIKeyHeader, APIKeyCookie, HTTPBearer, HTTPDigest, OpenIdConnect
from fastapi.testclient import TestClient
from starlette.status import HTTP_401_UNAUTHORIZED, HTTP_403_FORBIDDEN

app = FastAPI()

# Define schemes
api_key_query = APIKeyQuery(name="api_key")
api_key_header = APIKeyHeader(name="X-API-Key")
api_key_cookie = APIKeyCookie(name="api_key")
http_bearer = HTTPBearer()
http_digest = HTTPDigest()
oidc = OpenIdConnect(openIdConnectUrl="https://example.com/.well-known/openid-configuration")

@app.get("/query")
async def read_query(key: str = Depends(api_key_query)):
    return {"key": key}

@app.get("/header")
async def read_header(key: str = Depends(api_key_header)):
    return {"key": key}

@app.get("/cookie")
async def read_cookie(key: str = Depends(api_key_cookie)):
    return {"key": key}

@app.get("/bearer")
async def read_bearer(token: str = Depends(http_bearer)):
    return {"token": token}

@app.get("/digest")
async def read_digest(credentials: str = Depends(http_digest)):
    return {"credentials": credentials}

@app.get("/oidc")
async def read_oidc(token: str = Depends(oidc)):
    return {"token": token}

client = TestClient(app)

def test_schemes():
    schemes = [
        ("/query", "APIKeyQuery"),
        ("/header", "APIKeyHeader"),
        ("/cookie", "APIKeyCookie"),
        ("/bearer", "HTTPBearer"),
        ("/digest", "HTTPDigest"),
        ("/oidc", "OpenIdConnect"),
    ]

    for path, name in schemes:
        response = client.get(path)
        print(f"{name}: {response.status_code}")
        # Currently it is 403, we want it to be 401
        assert response.status_code == HTTP_403_FORBIDDEN, f"{name} should return 403 (current behavior)"

if __name__ == "__main__":
    try:
        test_schemes()
        print("All current checks passed (returned 403)")
    except AssertionError as e:
        print(f"Assertion failed: {e}")
        exit(1)

